    // Step 1: Create a new empty graph to hold the result
    Graph<V,E> resultGraph = new Graph<V,E>();

    // Step 2: Loop through each vertex in the input graph and add a new vertex to the result graph with the same name and any edges connected to it
    for (V vertex : graph.getVertices()) {
        V newVertex = resultGraph.addVertex(vertex.getName());
        for (E edge : graph.edgesOf(vertex)) {
            resultGraph.addEdge(edge.getSource(), edge.getTarget(), edge.getValue());
        }
    }

    // Step 3: Return the new graph mapping
    return new IsomorphicGraphMapping<V,E>(resultGraph, resultGraph);
}

public <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph) {
    // Check if the input graph is null
    if (graph == null) {
        throw new IllegalArgumentException("Input graph must not be null");
    }

    // Create a new IsomorphicGraphMapping object
    IsomorphicGraphMapping<V,E> mapping = new IsomorphicGraphMapping<V,E>();

    // Loop through the input graph and add each vertex to the mapping with itself as its image
    for (V vertex : graph.getVertices()) {
        mapping.put(vertex, vertex);
    }

    // Return the new IsomorphicGraphMapping object
    return mapping;
