public static List<ThreadSnapshot> ParseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges)
{
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (Stream<String> lines = Files.lines(file.toPath()))
    {
        for (String line : lines.collect(Collectors.toList()))
        {
            String[] parts = line.split(",");
            ThreadSnapshot threadSnapshot = new ThreadSnapshot();
            threadSnapshot.setThreadId(Long.parseLong(parts[0].trim()));
            threadSnapshot.setThreadState(parts[1].trim());
            threadSnapshot.setThreadWaitStatus(parts[2].trim());
            threadSnapshot.setThreadCPUTime(Long.parseLong(parts[3].trim()));
            threadSnapshot.setThreadAllocatedBytes(Long.parseLong(parts[4].trim()));
            threadSnapshot.setThreadAllocatedKB(Long.parseLong(parts[5].trim()));
            threadSnapshot.setThreadLastSweep(Long.parseLong(parts[6].trim()));
            threadSnapshots.add(threadSnapshot);
        }
    }
    catch (IOException e)
    {
        throw new IOException("Error reading file: " + file.getAbsolutePath(), e);
    }
    return threadSnapshots;
}

public List<ThreadSnapshot> loadThreadSnapshotsWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
  List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
  BufferedReader reader = new BufferedReader(new FileReader(file));
  String line;
  while ((line = reader.readLine()) != null) {
    if (isCommentLine(line)) {
      continue;
    }
    long timestamp = Long.parseLong(line.split(" ")[0]);
    if (timeRanges.stream().noneMatch(tr -> tr.isInTimeRange(timestamp))) {
      continue;
    }
    ThreadSnapshot snapshot = new ThreadSnapshot();
    snapshot.setTimestamp(timestamp);
    threadSnapshots.add(snapshot);
  }
  reader.close();
  return threadSnapshots;
}
